/// Assign a fixed, whole-second access time without changing file contents.
/// Read it back after closing the handle so fixture failures are explicit.
pub fn accessed<P: AsRef<Path>>(&self, name: P, rank: u64) {
    use std::{fs::FileTimes, time::{Duration, UNIX_EPOCH}};
    let path = self.dir.join(name);
    let expected = UNIX_EPOCH + Duration::from_secs(1_000_000_000 + rank * 120);
    {
        let file = nice_err(&path, File::options().write(true).open(&path));
        nice_err(&path, file.set_times(FileTimes::new().set_accessed(expected)));
    }
    let actual = nice_err(&path, nice_err(&path, fs::metadata(&path)).accessed());
    assert_eq!(actual, expected, "access-time fixture was not preserved: {path:?}");
}

