fn sort_setup(dir: Dir) {
    // Creation-time sleeps do not establish the access-time precondition.
    // Use explicit timestamps, preserving the existing sort assertions.
    dir.create_dir("dir");
    for (rank, name) in ["a", "dir/c", "b", "dir/d"].iter().enumerate() {
        dir.create(name, "test");
        dir.accessed(name, rank as u64);
    }
}

